import { spawn } from 'node:child_process';
import { createHash } from 'node:crypto';
import { mkdir, mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { findBrowser } from './browser-discovery.mjs';

const CARD_WIDTH = 1200;
const CARD_HEIGHT = 630;
const RENDERER_VERSION = 8;
const GENERATED_MARKER = '<!-- Generated by scripts/generate-social-cards.mjs. -->';
const SNAPSHOT_FETCH_TIMEOUT_MS = 15_000;
const SNAPSHOT_FETCH_ATTEMPTS = 3;
const SNAPSHOT_RETRY_DELAYS_MS = [1_000, 2_500];
const SOCIAL_START_MARKER = '<!-- CGB current-game social metadata: start -->';
const SOCIAL_END_MARKER = '<!-- CGB current-game social metadata: end -->';

function escapeHtml(value) {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

function titleSizeClass(title) {
  if (title.length > 20) return 'game-title--extra-long';
  if (title.length > 17) return 'game-title--long';
  if (title.length > 12) return 'game-title--medium';
  return 'game-title--default';
}

function sleep(ms) {
  return new Promise((resolvePromise) => setTimeout(resolvePromise, ms));
}

function retryableSnapshotError(message) {
  const error = new Error(message);
  error.retryable = true;
  return error;
}

async function fetchSnapshotAttempt(endpoint, validateSnapshot, {
  fetchImpl = fetch,
  timeoutMs = SNAPSHOT_FETCH_TIMEOUT_MS
} = {}) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);
  try {
    let response;
    try {
      response = await fetchImpl(endpoint, { signal: controller.signal, redirect: 'follow' });
    } catch (error) {
      if (error?.name === 'AbortError') throw retryableSnapshotError(`request timed out after ${timeoutMs / 1000} seconds`);
      throw retryableSnapshotError(error?.message || 'network request failed');
    }
    if (!response.ok) {
      const error = new Error(`HTTP ${response.status}`);
      error.retryable = response.status === 408 || response.status === 429 || response.status >= 500;
      throw error;
    }
    let snapshot;
    try {
      snapshot = await response.json();
    } catch (error) {
      throw new Error(`response was not valid JSON: ${error.message}`);
    }
    return validateSnapshot(snapshot);
  } finally {
    clearTimeout(timeout);
  }
}

export async function fetchSnapshot(endpoint, validateSnapshot, {
  fetchImpl = fetch,
  timeoutMs = SNAPSHOT_FETCH_TIMEOUT_MS,
  attempts = SNAPSHOT_FETCH_ATTEMPTS,
  retryDelaysMs = SNAPSHOT_RETRY_DELAYS_MS,
  sleepImpl = sleep
} = {}) {
  const maxAttempts = Number.isInteger(attempts) && attempts > 0 ? attempts : SNAPSHOT_FETCH_ATTEMPTS;
  let lastError;
  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
    try {
      return await fetchSnapshotAttempt(endpoint, validateSnapshot, { fetchImpl, timeoutMs });
    } catch (error) {
      lastError = error;
      if (!error?.retryable || attempt === maxAttempts) break;
      const delayMs = retryDelaysMs[Math.min(attempt - 1, retryDelaysMs.length - 1)] || 0;
      if (delayMs > 0) await sleepImpl(delayMs);
    }
  }
  const attemptDetail = lastError?.retryable && maxAttempts > 1 ? ` after ${maxAttempts} attempts` : '';
  throw new Error(`Unable to fetch the public Apps Script snapshot${attemptDetail}: ${lastError?.message || 'unknown error'}`);
}

function runBrowser(browser, args) {
  return new Promise((resolvePromise, reject) => {
    const child = spawn(browser, args, { stdio: ['ignore', 'ignore', 'pipe'] });
    let stderr = '';
    child.stderr.setEncoding('utf8');
    child.stderr.on('data', (chunk) => { stderr += chunk; });
    child.once('error', reject);
    child.once('close', (code) => {
      if (code === 0) resolvePromise();
      else reject(new Error(`Headless browser exited with code ${code}: ${stderr.slice(-2000)}`));
    });
  });
}

async function assertPngDimensions(path) {
  const png = await readFile(path);
  const signature = png.subarray(0, 8).toString('hex');
  if (signature !== '89504e470d0a1a0a' || png.length < 24) throw new Error(`Invalid PNG output: ${path}`);
  const width = png.readUInt32BE(16);
  const height = png.readUInt32BE(20);
  if (width !== CARD_WIDTH || height !== CARD_HEIGHT) throw new Error(`Unexpected PNG dimensions for ${path}: ${width}x${height}`);
}

async function renderPng(html, outputPath, browser, temporaryDirectory) {
  const sourcePath = join(temporaryDirectory, `${outputPath.split(/[\\/]/).at(-1)}.html`);
  await writeFile(sourcePath, html, 'utf8');
  await mkdir(dirname(outputPath), { recursive: true });
  await runBrowser(browser, [
    '--headless=new', '--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage',
    '--disable-lcd-text', '--disable-font-subpixel-positioning', '--hide-scrollbars',
    '--force-device-scale-factor=1', `--window-size=${CARD_WIDTH},${CARD_HEIGHT}`,
    `--screenshot=${resolve(outputPath)}`, pathToFileURL(sourcePath).href
  ]);
  await assertPngDimensions(outputPath);
}

function designToken(css, name) {
  const escaped = String(name).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const value = css.match(new RegExp(`${escaped}\\s*:\\s*(#[0-9a-f]{6})\\s*;`, 'i'))?.[1];
  if (!value) throw new Error(`Could not resolve social-card design token: ${name}`);
  return value;
}

export async function loadPublicRuntime(siteRoot) {
  const root = resolve(siteRoot);
  const [core, configModule, instanceModule, indexHtml, designSystemCss] = await Promise.all([
    import(pathToFileURL(join(root, 'js', 'core.mjs')).href),
    import(pathToFileURL(join(root, 'js', 'config.mjs')).href),
    import(pathToFileURL(join(root, 'js', 'instance-config.mjs')).href),
    readFile(join(root, 'index.html'), 'utf8'),
    readFile(join(root, 'css', 'design-system.css'), 'utf8')
  ]);
  const config = instanceModule.ACTIVE_INSTANCE_CONFIG;
  const buildConfig = configModule.readBuildConfigFromHtml(indexHtml);
  const endpoint = buildConfig.dataEndpoint;
  if (!endpoint) throw new Error('Could not resolve the public data endpoint.');
  const endpointUrl = new URL(endpoint);
  if (endpointUrl.protocol !== 'https:' || endpointUrl.hostname !== 'script.google.com') {
    throw new Error(`Refusing unexpected snapshot endpoint: ${endpointUrl.origin}`);
  }
  return {
    root,
    core,
    config,
    indexHtml,
    endpoint,
    siteOrigin: buildConfig.canonicalSiteUrl.replace(/\/$/, ''),
    colors: {
      navy: designToken(designSystemCss, '--brand-loading-background'),
      gold: designToken(designSystemCss, '--brand-secondary'),
      white: designToken(designSystemCss, '--brand-surface'),
      mutedNavy: designToken(designSystemCss, '--brand-social-muted')
    }
  };
}

export function validateSocialSnapshot(snapshot, core) {
  if (snapshot?.ok === false) throw new Error(`Public snapshot endpoint reported ${String(snapshot.error || 'an unknown error')}.`);
  if (!core.validateSnapshotShape(snapshot)) throw new Error('Snapshot is missing required public arrays or contains invalid venue coordinates.');
  const seenGameIds = new Set();
  const seenSlugs = new Set();
  for (const game of snapshot.games) {
    const gameId = String(game?.game_id || '').trim();
    const opponent = String(game?.opponent_name || '').trim();
    const slug = core.gameRouteParam(game);
    if (!gameId || !opponent || !slug) throw new Error('Every game must have a game_id, opponent_name, and route slug.');
    if (seenGameIds.has(gameId)) throw new Error(`Duplicate game_id in snapshot: ${gameId}`);
    if (seenSlugs.has(slug)) throw new Error(`Duplicate game route slug in snapshot: ${slug}`);
    seenGameIds.add(gameId);
    seenSlugs.add(slug);
  }
  return snapshot;
}

function instanceCalendarDate(timeZone, now = new Date()) {
  const parts = Object.fromEntries(new Intl.DateTimeFormat('en-US', {
    timeZone, year: 'numeric', month: '2-digit', day: '2-digit'
  }).formatToParts(now).filter((part) => part.type !== 'literal').map((part) => [part.type, part.value]));
  return new Date(Number(parts.year), Number(parts.month) - 1, Number(parts.day), 12, 0, 0);
}

export function socialCardModel(snapshot, game, runtime) {
  const slug = runtime.core.gameRouteParam(game);
  const title = `${runtime.config.identity.schoolShortName} ${runtime.core.gameTitle(game)}`;
  const locationCount = snapshot.venues.length;
  const watchPartyCount = snapshot.watchParties.filter((party) => party?.game_id === game.game_id).length;
  const shareUrl = `${runtime.siteOrigin}/share/${slug}/`;
  const fingerprint = createHash('sha256')
    .update(JSON.stringify([RENDERER_VERSION, title, locationCount, watchPartyCount]))
    .digest('hex')
    .slice(0, 10);
  const imagePath = `${runtime.config.brand.assets.socialCardsDirectory}/${slug}-${fingerprint}.png`;
  const imageUrl = `${runtime.siteOrigin}/${imagePath}`;
  return {
    gameId: game.game_id, slug, title, locationCount, watchPartyCount, shareUrl, imagePath, imageUrl,
    metadataTitle: `${runtime.config.identity.productName} · ${title}`,
    metadataDescription: `${locationCount} locations mapped · ${watchPartyCount} Watch ${watchPartyCount === 1 ? 'Party' : 'Parties'}. ${runtime.config.copy.findCrowd}.`
  };
}

function sortGames(games) {
  return [...games].sort((a, b) => Number(a.season || 0) - Number(b.season || 0) || Number(a.schedule_order || 0) - Number(b.schedule_order || 0) || String(a.game_id).localeCompare(String(b.game_id)));
}

export function buildSocialManifest(snapshot, models, runtime, now = new Date()) {
  const defaultGame = runtime.core.selectDefaultGame(snapshot.games, instanceCalendarDate(runtime.config.schedule.homeTimeZone, now));
  const defaultGameSlug = runtime.core.gameRouteParam(defaultGame);
  if (!defaultGameSlug || !models.some((model) => model.slug === defaultGameSlug)) throw new Error('Could not select a generated social card for the default game.');
  return {
    version: 1,
    renderer_version: RENDERER_VERSION,
    default_game_slug: defaultGameSlug,
    games: models.map((model) => ({
      game_id: model.gameId, slug: model.slug, title: model.title,
      locations_mapped: model.locationCount, watch_parties: model.watchPartyCount,
      image: model.imagePath,
      page: `share/${model.slug}/index.html`
    }))
  };
}

